-- Actual existing server commands under rolled-back synthetic terms; no commercial approval or hosted data.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer)returns uuid language sql immutable as $$select('d2060000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.claim(n integer)returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'session_id',pg_temp.id(n+10),'role','authenticated','user_metadata',jsonb_build_object('paid',true,'staff_limit',9999,'clinic_limit',9999,'plan','unlimited'))::text,true)$$;
create function pg_temp.command(query text)returns void language plpgsql security invoker as $$begin execute query;set constraints doctor_saas_clinics_final,doctor_saas_members_final,doctor_saas_invitations_final immediate;set constraints doctor_saas_clinics_final,doctor_saas_members_final,doctor_saas_invitations_final deferred;end $$;
create function pg_temp.clinic(practice integer,key integer)returns text language sql as $$select format('select public.doctor_write_location(%L,%L,%L,%L,%L,%L)',pg_temp.id(practice),'Synthetic denied allocation','Etc/UTC','','',pg_temp.id(key))$$;
create function pg_temp.rename_clinic()returns text language sql as $$select format('select public.doctor_write_location(p_practice=>%L,p_name=>%L,p_timezone=>%L,p_phone=>%L,p_address=>%L,p_key=>%L,p_location=>%L,p_expected_version=>1)',pg_temp.id(21),'Synthetic retained renamed clinic','Etc/UTC','','',pg_temp.id(71),pg_temp.id(101))$$;
insert into auth.users(id,email,email_confirmed_at)select pg_temp.id(n),'synthetic-m6-entitlement-'||n||'@example.test',now()from generate_series(1,3)n;
insert into auth.sessions(id,user_id)select pg_temp.id(n+10),pg_temp.id(n)from generate_series(1,3)n;
insert into public.doctor_candidate_admissions(user_id,purpose,evidence_ref,valid_until)select pg_temp.id(n),'synthetic_fixture','disposable-m6-002:'||n,clock_timestamp()+interval'2 hours'from generate_series(1,3)n;
insert into public.doctor_profiles(user_id,display_name)values(pg_temp.id(1),'Synthetic active owner'),(pg_temp.id(2),'Synthetic expired owner');
insert into public.practices(id,owner_user_id,name)values(pg_temp.id(21),pg_temp.id(1),'Synthetic active practice'),(pg_temp.id(22),pg_temp.id(2),'Synthetic expired practice');
insert into public.locations(id,practice_id,name,timezone)values(pg_temp.id(101),pg_temp.id(21),'Synthetic retained clinic A','Etc/UTC'),(pg_temp.id(102),pg_temp.id(22),'Synthetic retained clinic B','Etc/UTC');
insert into public.memberships(id,practice_id,user_id,capabilities)values(pg_temp.id(301),pg_temp.id(21),pg_temp.id(3),array['patients.read']);
insert into public.membership_locations(practice_id,membership_id,location_id)values(pg_temp.id(21),pg_temp.id(301),pg_temp.id(101));
-- Drain preview-only fixture allocations before selecting candidate authority.
set constraints all immediate;
set constraints all deferred;
insert into public.doctor_saas_terms_versions(id,plan_key,version,status,currency,currency_exponent,monthly_minor,trial_days,staff_limit,staff_unlimited,clinic_limit,clinic_unlimited,over_limit_policy,renewal_policy,grace_days,expiry_policy,cancellation_policy,refund_policy,terms_document_ref,commercial_approval_ref,legal_approval_ref)values
(pg_temp.id(51),'synthetic-m6-002',1,'approved','USD',2,1234,2,1,false,1,false,'block_new_allocation','manual',0,'historical_read_only','period_end','manual_review','synthetic-m6-002/v1','SYNTHETIC_NOT_COMMERCIAL_APPROVAL','SYNTHETIC_NOT_LEGAL_APPROVAL');
update public.doctor_saas_configuration set terms_version_id=pg_temp.id(51),revision=2,change_reason='Disposable M6-002 fixture only';
with moment as(select clock_timestamp()at time zone'UTC'as stamp)
insert into public.doctor_saas_periods(id,subscriber_user_id,terms_version_id,kind,started_at,ends_at,accepted_document_ref)
select pg_temp.id(62),pg_temp.id(2),pg_temp.id(51),'trial',(stamp-interval'3 days')at time zone'UTC',(stamp-interval'1 day')at time zone'UTC','synthetic-m6-002/v1'from moment;
insert into public.doctor_saas_accounts(subscriber_user_id,current_period_id,state,reason_code)values(pg_temp.id(2),pg_temp.id(62),'enabled','trial_started');
update public.doctor_edition_policy set mode='administrative_candidate',revision=2,change_reason='Explicit synthetic M6-002 verification';
set local role authenticated;select pg_temp.claim(1);
select is(public.doctor_saas_status()->>'state','unconfigured','forged paid/unlimited metadata cannot create a subscription');
select throws_ok($$select pg_temp.command(pg_temp.clinic(21,70))$$,'DS006','DOCTOR_SAAS_PERIOD_INACTIVE','unconfigured owner cannot allocate with forged plan');
select public.doctor_start_saas_trial(pg_temp.id(51),2,'synthetic-m6-002/v1',pg_temp.id(61));
select is(public.doctor_saas_status()->>'state','trial','server immutable trial supplies current state');
select is(public.doctor_saas_status()#>>'{usage,clinics}','1','usage is scoped to this owner rather than both doctors');
select is(public.doctor_saas_status()#>>'{usage,staff_total}','1','owner excluded and one independent membership counted');
select is(public.doctor_saas_status()->>'paid_activation_available','false','trial and metadata cannot enable paid activation');
select throws_ok($$select pg_temp.command(pg_temp.clinic(21,72))$$,'DS003','DOCTOR_SAAS_CLINIC_LIMIT','current clinic quota defeats forged unlimited metadata');
select throws_ok($$select pg_temp.command(format('select public.doctor_invite_secretary(%L,%L,%L,%L::jsonb,%L)',pg_temp.id(21),'synthetic-m6-extra@example.test',encode(sha256(decode(repeat('ab',32),'hex')),'hex'),jsonb_build_array(jsonb_build_object('location_id',pg_temp.id(101),'capabilities',jsonb_build_array('patients.read'))),pg_temp.id(73)))$$,'DS002','DOCTOR_SAAS_STAFF_LIMIT','current named-staff quota defeats forged metadata');
select lives_ok($$select pg_temp.command(pg_temp.rename_clinic())$$,'ordinary authorized edit remains available at capacity');
select lives_ok($$select pg_temp.command(pg_temp.rename_clinic())$$,'exact command replay creates no new allocation');
select throws_ok($$select pg_temp.command(pg_temp.clinic(22,74))$$,'42501',null,'active owner cannot fund another doctor practice');
reset role;
select is((select version from public.locations where id=pg_temp.id(101)),2,'exact replay retains one accepted update');
select is((select count(*)::integer from doctor_private.command_receipts where command_key=pg_temp.id(71)),1,'one receipt for exact command despite replay');
select is((select count(*)::integer from doctor_private.command_receipts where command_key in(pg_temp.id(70),pg_temp.id(72),pg_temp.id(73),pg_temp.id(74))),0,'failed allocations leave no success receipt');
select is((select count(*)::integer from public.locations where practice_id=pg_temp.id(21)),1,'quota denials retain one original clinic and its history');
set local role authenticated;select pg_temp.claim(2);
select is(public.doctor_saas_status()->>'state','expired','server original period dates determine expiry');
select is(public.doctor_saas_status()->>'business_writes_allowed','false','expired state denies ordinary writes despite paid metadata');
select is(public.doctor_saas_status()#>>'{period,id}',pg_temp.id(62)::text,'expired owner retains original period history');
select is(public.doctor_saas_status()#>>'{usage,clinics}','1','expired history keeps owned location usage');
select is(public.doctor_locations(pg_temp.id(22),0,20,'')->>'total','1','expired owner retains the actual scoped historical clinic count');
select is(public.doctor_locations(pg_temp.id(22),0,20,'')#>>'{rows,0,id}',pg_temp.id(102)::text,'expired owner reads their retained clinic instead of an empty success');
select throws_ok($$select pg_temp.command(pg_temp.clinic(22,75))$$,'DS006','DOCTOR_SAAS_PERIOD_INACTIVE','expired owner cannot allocate or renew using metadata');
select pg_temp.claim(3);
select throws_ok($$select public.doctor_saas_status()$$,'42501','DOCTOR_OWNER_ENROLLMENT_REQUIRED','secretary membership cannot read or enroll in owner subscription');
reset role;
update public.doctor_saas_accounts set state='suspended',revision=2,reason_code='operator_hold'where subscriber_user_id=pg_temp.id(1);
set local role authenticated;select pg_temp.claim(1);
select is(public.doctor_saas_status()->>'state','suspended','fresh hold is current server authority');
select is(public.doctor_saas_status()->>'business_writes_allowed','false','hold cannot be undone by cached client plan');
select throws_ok($$select pg_temp.command(pg_temp.clinic(21,76))$$,'DS006','DOCTOR_SAAS_PERIOD_INACTIVE','held writes remain denied');
reset role;
select is((select count(*)::integer from public.locations),2,'expiry/hold/quota failures delete no retained clinic');
select is((select count(*)::integer from public.doctor_saas_periods where subscriber_user_id in(pg_temp.id(1),pg_temp.id(2))),2,'current and historical immutable periods remain');
select throws_ok($$delete from public.doctor_saas_periods where id=pg_temp.id(62)$$,'42501','DOCTOR_SAAS_HISTORY_IMMUTABLE','history cannot be erased to enforce a plan');
select ok(not has_table_privilege('authenticated','public.doctor_saas_accounts','UPDATE'),'browser cannot overwrite current subscription');
select ok(not has_function_privilege('service_role','doctor_private.saas_allocation_state(uuid,boolean)','EXECUTE'),'service API cannot substitute private quota authority');
select * from finish();
rollback;
